USE MotoGP;
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRY
BEGIN TRANSACTION;
IF OBJECT_ID('tempdb..#t_sessions') IS NOT NULL DROP TABLE #t_sessions;
CREATE TABLE #t_sessions([sid] uniqueidentifier,[event_uuid] uniqueidentifier,[class_name] nvarchar(50),[type] varchar(10),[number] smallint,[date] nvarchar(50),[status] nvarchar(50),[url] nvarchar(1000));
IF OBJECT_ID('tempdb..#t_entries') IS NOT NULL DROP TABLE #t_entries;
CREATE TABLE #t_entries([sid] uniqueidentifier,[key] varchar(60),[legacy_id] int,[uuid] uniqueidentifier,[name] nvarchar(200),[number] smallint);
IF OBJECT_ID('tempdb..#t_revisions') IS NOT NULL DROP TABLE #t_revisions;
CREATE TABLE #t_revisions([revision] char(64),[sid] uniqueidentifier,[created_at] nvarchar(50),[parser_version] varchar(20));
IF OBJECT_ID('tempdb..#t_documents') IS NOT NULL DROP TABLE #t_documents;
CREATE TABLE #t_documents([revision] char(64),[sid] uniqueidentifier,[kind] varchar(30),[url] nvarchar(1000),[sha256] char(64),[retrieved_at] nvarchar(50),[parse_status] varchar(25),[row_count] int,[note] nvarchar(1000));
IF OBJECT_ID('tempdb..#t_qualifying') IS NOT NULL DROP TABLE #t_qualifying;
CREATE TABLE #t_qualifying([revision] char(64),[sid] uniqueidentifier,[key] varchar(60),[position] smallint,[source_status] nvarchar(50),[best_lap_seconds] decimal(12,3),[best_lap_number] smallint,[total_laps] smallint,[top_speed_kmh] decimal(7,3),[source_time] nvarchar(50));
IF OBJECT_ID('tempdb..#t_records') IS NOT NULL DROP TABLE #t_records;
CREATE TABLE #t_records([revision] char(64),[sid] uniqueidentifier,[key] varchar(60),[record_type] varchar(30),[record_year] smallint,[lap_number] smallint,[lap_time_seconds] decimal(12,3),[is_new_record] bit,[source_time] nvarchar(50));
IF OBJECT_ID('tempdb..#t_fastest') IS NOT NULL DROP TABLE #t_fastest;
CREATE TABLE #t_fastest([revision] char(64),[sid] uniqueidentifier,[source_rider_key] varchar(60),[rider_number] smallint,[published_rank] smallint,[best_lap_seconds] decimal(12,3),[best_lap_number] smallint,[total_laps] smallint,[source_text] nvarchar(1000),[page] smallint);
IF OBJECT_ID('tempdb..#t_grids') IS NOT NULL DROP TABLE #t_grids;
CREATE TABLE #t_grids([revision] char(64),[sid] uniqueidentifier,[source_rider_key] varchar(60),[rider_number] smallint,[grid_position] smallint,[qualifying_time_seconds] decimal(12,3),[grid_status] varchar(20),[source_text] nvarchar(1000),[page] smallint);
IF OBJECT_ID('tempdb..#t_laps') IS NOT NULL DROP TABLE #t_laps;
CREATE TABLE #t_laps([revision] char(64),[sid] uniqueidentifier,[source_rider_key] varchar(60),[rider_number] smallint,[lap_number] smallint,[lap_time_seconds] decimal(12,3),[lap_time_cancelled] bit,[pit_lane_crossing] bit,[sector1_seconds] decimal(10,3),[sector2_seconds] decimal(10,3),[sector3_seconds] decimal(10,3),[sector4_seconds] decimal(10,3),[sector1_cancelled] bit,[sector2_cancelled] bit,[sector3_cancelled] bit,[sector4_cancelled] bit,[speed_kmh] decimal(7,3),[page] smallint,[source_text] nvarchar(1000));
IF OBJECT_ID('tempdb..#t_issues') IS NOT NULL DROP TABLE #t_issues;
CREATE TABLE #t_issues([revision] char(64),[sid] uniqueidentifier,[issue_number] int,[component] varchar(40),[reason] nvarchar(1000));

IF OBJECT_ID(N'dbo.timing_sessions',N'U') IS NULL THROW 50100,'Run 21_create_timing_tables.sql first.',1;
IF EXISTS(SELECT 1 FROM #t_sessions x LEFT JOIN dbo.events e ON e.source_event_uuid=x.event_uuid
 LEFT JOIN dbo.classes c ON c.class_name=x.class_name
 LEFT JOIN dbo.event_classes ec ON ec.event_id=e.event_id AND ec.class_id=c.class_id
 WHERE ec.event_class_id IS NULL) THROW 50101,'Timing import has missing event/class links. Check calendar import.',1;
IF EXISTS(SELECT 1 FROM #t_sessions x LEFT JOIN motogp_source.race_sessions rs ON rs.source_session_uuid=x.sid
 WHERE x.type IN('RAC','SPR') AND rs.source_session_uuid IS NULL)
 THROW 50102,'Load 16_history_2025_results.sql before timing data.',1;
IF EXISTS(SELECT 1 FROM #t_revisions x JOIN dbo.timing_revisions r ON r.sid=x.sid AND r.is_current=1 WHERE r.revision<>x.revision)
 THROW 50103,'Timing source or parser revision changed. Review before replacing the accepted revision.',1;
SELECT x.sid,ec.event_class_id,x.type,x.number,x.date,x.status,x.url
FROM #t_sessions x JOIN dbo.events e ON e.source_event_uuid=x.event_uuid
JOIN dbo.classes c ON c.class_name=x.class_name
JOIN dbo.event_classes ec ON ec.event_id=e.event_id AND ec.class_id=c.class_id
WHERE NOT EXISTS(SELECT 1 FROM dbo.timing_sessions t WHERE t.sid=x.sid);
IF EXISTS(SELECT 1 FROM #t_sessions x JOIN dbo.timing_sessions t ON t.sid=x.sid
 JOIN motogp_source.race_sessions rs ON rs.source_session_uuid=x.sid
 JOIN dbo.races r ON r.race_id=rs.race_id WHERE t.event_class_id<>r.event_class_id)
 THROW 50104,'Race and timing session contexts differ.',1;
SELECT x.sid,x.[key],x.legacy_id,x.uuid,x.name,x.number,sr.rider_id
FROM #t_entries x LEFT JOIN motogp_source.riders sr ON sr.motogp_legacy_id=x.legacy_id
 AND (x.uuid IS NULL OR sr.source_rider_uuid=x.uuid)
WHERE NOT EXISTS(SELECT 1 FROM dbo.session_entries t WHERE t.sid=x.sid AND t.[key]=x.[key]);
SELECT x.revision,x.sid,x.created_at,x.parser_version,1 FROM #t_revisions x
WHERE NOT EXISTS(SELECT 1 FROM dbo.timing_revisions t WHERE t.revision=x.revision);
SELECT x.[revision],x.[sid],x.[kind],x.[url],x.[sha256],x.[retrieved_at],x.[parse_status],x.[row_count],x.[note] FROM #t_documents x
WHERE NOT EXISTS(SELECT 1 FROM dbo.timing_documents t WHERE t.revision=x.revision);
SELECT x.[revision],x.[sid],x.[key],x.[position],x.[source_status],x.[best_lap_seconds],x.[best_lap_number],x.[total_laps],x.[top_speed_kmh],x.[source_time] FROM #t_qualifying x
WHERE NOT EXISTS(SELECT 1 FROM dbo.session_results t WHERE t.revision=x.revision);
SELECT x.[revision],x.[sid],x.[key],x.[record_type],x.[record_year],x.[lap_number],x.[lap_time_seconds],x.[is_new_record],x.[source_time] FROM #t_records x
WHERE NOT EXISTS(SELECT 1 FROM dbo.session_lap_records t WHERE t.revision=x.revision);
SELECT x.[revision],x.[sid],x.[source_rider_key],x.[rider_number],x.[published_rank],x.[best_lap_seconds],x.[best_lap_number],x.[total_laps],x.[source_text],x.[page] FROM #t_fastest x
WHERE NOT EXISTS(SELECT 1 FROM dbo.race_fastest_laps t WHERE t.revision=x.revision);
SELECT x.[revision],x.[sid],x.[source_rider_key],x.[rider_number],x.[grid_position],x.[qualifying_time_seconds],x.[grid_status],x.[source_text],x.[page] FROM #t_grids x
WHERE NOT EXISTS(SELECT 1 FROM dbo.race_grids t WHERE t.revision=x.revision);
SELECT x.[revision],x.[sid],x.[source_rider_key],x.[rider_number],x.[lap_number],x.[lap_time_seconds],x.[lap_time_cancelled],x.[pit_lane_crossing],x.[sector1_seconds],x.[sector2_seconds],x.[sector3_seconds],x.[sector4_seconds],x.[sector1_cancelled],x.[sector2_cancelled],x.[sector3_cancelled],x.[sector4_cancelled],x.[speed_kmh],x.[page],x.[source_text] FROM #t_laps x
WHERE NOT EXISTS(SELECT 1 FROM dbo.lap_times t WHERE t.revision=x.revision);
SELECT x.[revision],x.[sid],x.[issue_number],x.[component],x.[reason] FROM #t_issues x
WHERE NOT EXISTS(SELECT 1 FROM dbo.timing_quality_issues t WHERE t.revision=x.revision);

SELECT (SELECT COUNT(*) FROM #t_sessions) AS sessions_in_seed,
 (SELECT COUNT(*) FROM #t_qualifying) AS qualifying_rows_in_seed,
 (SELECT COUNT(*) FROM #t_fastest) AS fastest_lap_rows_in_seed,
 (SELECT COUNT(*) FROM #t_grids) AS grid_rows_in_seed,
 (SELECT COUNT(*) FROM #t_laps) AS lap_rows_in_seed;
SELECT COUNT(*) AS timing_entries_without_rider_link FROM dbo.session_entries e
JOIN #t_sessions x ON x.sid=e.sid WHERE e.rider_id IS NULL;
COMMIT TRANSACTION;
END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
 THROW;
END CATCH;
GO
